package com.bank.model;

public class Account {
    private int accNo;
    private String holder;
    private String email;
    private double balance;
    private String status;

    /** For a brand-new account (accNo is generated by the database). */
    public Account(String holder, String email, double balance) {
        this.holder = holder;
        this.email = email;
        this.balance = balance;
        this.status = "ACTIVE";
    }

    /** For an account read from the database. */
    public Account(int accNo, String holder, String email, double balance, String status) {
        this.accNo = accNo;
        this.holder = holder;
        this.email = email;
        this.balance = balance;
        this.status = status;
    }

    public int getAccNo()      { return accNo; }
    public String getHolder()  { return holder; }
    public String getEmail()   { return email; }
    public double getBalance() { return balance; }
    public String getStatus()  { return status; }

    @Override
    public String toString() {
        return String.format("Acc %-5d | %-12s | %-22s | %12.2f | %s",
                accNo, holder, email, balance, status);
    }
}
